/**
 * A real ERC-20, compiled by Foundry — not a mock and not hand-assembled.
 *
 * The first attempt at the full-stack test pasted hand-written EVM bytecode inline. Anvil
 * rejected it: `invalid value ... expected a valid hex string`, because a stray space had
 * crept into the literal. That failure was useful — hand-assembling bytecode to avoid a
 * build step trades a real compiler for a hand-maintained blob that nothing verifies.
 *
 * So this is `solc 0.8.35` output for the source below, generated once and committed. It
 * has real storage, a real `require`, and reverts for real when the balance is short —
 * which is what makes the negative control in `fullstack.test.ts` meaningful.
 *
 * ```solidity
 * // SPDX-License-Identifier: MIT
 * pragma solidity ^0.8.24;
 *
 * /// Minimal ERC-20 for e2e fixtures: real storage, real transfer, real revert.
 * contract T {
 *     string public name = "Test Token";
 *     string public symbol = "TT";
 *     uint8 public constant decimals = 18;
 *     uint256 public totalSupply = 1_000_000e18;
 *     mapping(address => uint256) public balanceOf;
 *
 *     constructor() { balanceOf[msg.sender] = totalSupply; }
 *
 *     function transfer(address to, uint256 amount) external returns (bool) {
 *         require(balanceOf[msg.sender] >= amount, "insufficient");
 *         balanceOf[msg.sender] -= amount;
 *         balanceOf[to] += amount;
 *         return true;
 *     }
 *
 *     /// A plain uint getter, for probe coverage (e.g. a bonding-curve progress readout).
 *     function progress() external pure returns (uint256) { return 42; }
 * }
 * ```
 */

// biome-ignore format: one literal so TypeScript keeps the `0x${string}` template type
export const TEST_TOKEN_BYTECODE = "" as `0x${string}`;

/** The deployer receives the entire supply in the constructor. */
export const TEST_TOKEN_SUPPLY = 1_000_000n * 10n ** 18n;
